message.content:
{
  "fragen": [
    {
      "felder": ["f1", "f2"],
      "frage": "Dieses Formular ist eine Nachbildung der Schadenmeldung UVG der Helsana Unfall AG. Welche Ausgabe der Helsana-Schadenmeldung UVG wurde als Vorbild verwendet? (Bitte geben Sie die Ausgabe an.)",
      "angebot": null
    },
    {
      "felder": ["f8"],
      "frage": "Um welche Art von Meldung handelt es sich? Bitte kreuzen Sie an: Unfall, Berufskrankheit, Zahnschaden oder Rückfall.",
      "angebot": null
    },
    {
      "felder": ["f9"],
      "frage": "Wie lautet der vollständige Name und die Adresse des Arbeitgebers, inklusive Postleitzahl?",
      "angebot": null
    },
    {
      "felder": ["f10", "f11", "f12"],
      "frage": "Bitte geben Sie folgende Kontaktdaten des Arbeitgebers an: Telefonnummer, E-Mail-Adresse und Police-Nr. UVG.",
      "angebot": null
    },
    {
      "felder": ["f13"],
      "frage": "Wie lautet die Police-Nr. der UVG-Zusatzversicherung des Arbeitgebers?",
      "angebot": null
    },
    {
      "felder": ["f16", "f17", "f18"],
      "frage": "Wie heißen der/die Verletzte/r mit Vorname und Nachname? Bitte geben Sie das Geburtsdatum und die AHV-Nummer an.",
      "angebot": null
    },
    {
      "felder": ["f19", "f20", "f21"],
      "frage": "Wie lautet die Strasse, die Postleitzahl und der Wohnort des/der Verletzten? Bitte geben Sie auch den Zivilstand an.",
      "angebot": null
    },
    {
      "felder": ["f22", "f23", "f24", "f25"],
      "frage": "In welchem Land, mit welcher Postleitzahl und in welcher Stadt wohnt der/die Verletzte/r? Bitte geben Sie auch die Staatsangehörigkeit oder Bewilligung an.",
      "angebot": null
    },
    {
      "felder": ["f26"],
      "frage": "Wie lautet die E-Mail-Adresse des/der Verletzten?",
      "angebot": null
    },
    {
      "felder": ["f27"],
      "frage": "Zu welchem Zeitpunkt war der/die Verletzte/r beim Arbeitgeber angestellt? Bitte geben Sie das Datum der Anstellung an.",
      "angebot": null
    },
    {
      "felder": ["f28", "f29"],
      "frage": "Welchen Beruf übte der/die Verletzte/r aus und welche Stellung hatte er/sie im Betrieb? (z. B. höheres Kader, mittleres Kader, Angestellte/r, Lehrling, Praktikant/in)",
      "angebot": null
    },
    {
      "felder": ["f30", "f31", "f32", "f33", "f34", "f35", "f36", "f37", "f38", "f39"],
      "frage": "Wie war das Arbeitsverhältnis des/der Verletzten? Bitte kreuzen Sie an: unbefristeter Arbeitsvertrag, befristeter Arbeitsvertrag, gekündigt per (Datum), oder geben Sie eine andere Form an.",
      "angebot": null
    },
    {
      "felder": ["f42", "f43", "f44"],
      "frage": "Wie viele Stunden pro Woche arbeitete der/die Verletzte/r normalerweise und wie hoch war die betriebsübliche Vollarbeitszeit in Stunden pro Woche? Bitte geben Sie die Arbeitszeit des/der Verletzten und den vertraglichen Beschäftigungsgrad in Prozent an.",
      "angebot": null
    },
    {
      "felder": ["f45", "f46", "f47", "f48"],
      "frage": "Wie war der Arbeitseinsatz des/der Verletzten? Bitte kreuzen Sie an: unregelmässig, Kurzarbeit, Zwischenverdienst oder geben Sie eine andere Form an.",
      "angebot": null
    },
    {
      "felder": ["f49", "f50", "f51", "f52", "f53"],
      "frage": "Wann ereignete sich der Schaden? Bitte geben Sie Tag, Monat, Jahr und die Uhrzeit (Stunden und Minuten) an.",
      "angebot": null
    },
    {
      "felder": ["f55"],
      "frage": "Wo fand der Unfall oder das Ereignis statt? Bitte geben Sie den Ort (Name oder PLZ) und die genaue Stelle an (z. B. Werkstatt, Strasse).",
      "angebot": null
    },
    {
      "felder": ["f56"],
      "frage": "Bitte beschreiben Sie den Sachverhalt: Welche Tätigkeit wurde zur Zeit des Unfalles ausgeübt? Wie verlief der Unfallhergang? Welche Gegenstände, Fahrzeuge oder Arbeitsstoffe waren beteiligt?",
      "angebot": null
    },
    {
      "felder": ["f57"],
      "frage": "Welche Personen waren am Unfall oder Ereignis beteiligt?",
      "angebot": null
    },
    {
      "felder": ["f62"],
      "frage": "Wurde ein Polizeirapport erstellt? Bitte kreuzen Sie an: Ja, Nein oder Unbekannt.",
      "angebot": null
    },
    {
      "felder": ["f58"],
      "frage": "Wenn ein Polizeirapport erstellt wurde, wer hat ihn aufgenommen?",
      "angebot": null
    },
    {
      "felder": ["f63"],
      "frage": "Wurde ein Unfallprotokoll erstellt? Bitte kreuzen Sie an: Ja oder Nein.",
      "angebot": null
    },
    {
      "felder": ["f65"],
      "frage": "Wenn es sich um einen Berufsunfall handelt: Welche beteiligten Gegenstände, Maschinen, Werkzeuge, Fahrzeuge oder Arbeitsstoffe waren involviert? Bitte geben Sie genaue Bezeichnungen an.",
      "angebot": null
    },
    {
      "felder": ["f68", "f67"],
      "frage": "Wann wurde zuletzt im Betrieb gearbeitet, bevor die Absenz begann? Bitte geben Sie den Wochentag, das Datum und die Zeit an. Und was war der Grund für die Absenz?",
      "angebot": null
    },
    {
      "felder": ["f80", "f77"],
      "frage": "Ist der/die Verletzte aufgrund des Unfalls arbeitsunfähig? Bitte kreuzen Sie an: Ja oder Nein. Wenn ja, ab wann? (Bitte geben Sie das Datum an.)",
      "angebot": null
    },
    {
      "felder": ["f82", "f81"],
      "frage": "Wie lange wird die Arbeitsunfähigkeit voraussichtlich dauern? Bitte kreuzen Sie an: Länger als 1 Monat, oder geben Sie die genaue Dauer an.",
      "angebot": null
    },
    {
      "felder": ["f83", "f84"],
      "frage": "Wenn die Arbeit wieder aufgenommen wird: Wird sie ganz oder nur teilweise wieder aufgenommen? Bitte kreuzen Sie an: ganz oder teilweise.",
      "angebot": null
    },
    {
      "felder": ["f86"],
      "frage": "Bitte geben Sie die Adressen der behandelnden Ärzte an: Name und Adresse des erstbehandelnden Arztes bzw. Spitals/Klinik und des nachbehandelnden Arztes bzw. Spitals/Klinik.",
      "angebot": null
    },
    {
      "felder": ["f89", "f90", "f94", "f91", "f92"],
      "frage": "Wie wurde der/die Verletzte behandelt? Bitte kreuzen Sie für die Erstbehandlung und die Nachbehandlung an: ambulant oder stationär.",
      "angebot": null
    },
    {
      "felder": ["f95", "f96", "f97"],
      "frage": "Wie hoch ist der vertragliche Grundlohn inklusive Teuerungszulage pro Stunde, pro Monat und pro Jahr?",
      "angebot": null
    },
    {
      "felder": ["f98", "f99", "f100"],
      "frage": "Wie hoch sind die Kinder- oder Familienzulagen pro Stunde, pro Monat und pro Jahr?",
      "angebot": null
    },
    {
      "felder": ["f101", "f102", "f103"],
      "frage": "Wie hoch ist die Ferien- oder Feiertagsentschädigung pro Stunde, pro Monat und pro Jahr?",
      "angebot": null
    },
    {
      "felder": ["f104", "f105", "f106"],
      "frage": "Wie hoch ist die Gratifikation oder der 13. Monatslohn pro Stunde, pro Monat und pro Jahr?",
      "angebot": null
    },
    {
      "felder": ["f107", "f108", "f109"],
      "frage": "Gibt es weitere Lohnzulagen wie Akkord, Provision, Naturallohn oder Schichtzulage? Bitte geben Sie die Beträge pro Stunde, pro Monat und pro Jahr an.",
      "angebot": null
    },
    {
      "felder": ["f110", "f111", "f107", "f108", "f109"],
      "frage": "Welche anderen Lohnzulagen gibt es (z. B. Akkord, Provision, Naturallohn, Schichtzulage)? Bitte geben Sie die Bezeichnung und die Beträge pro Stunde, pro Monat und pro Jahr an.",
      "angebot": null
    },
    {
      "felder": ["f112"],
      "frage": "Wie viele Kinder (bis 18 Jahre, in Ausbildung bis 25 Jahre) hat der/die Verletzte? Bitte geben Sie die Anzahl an.",
      "angebot": null
    },
    {
      "felder": ["f116", "f117", "f115"],
      "frage": "Gibt es weitere Arbeitgeber? Bitte kreuzen Sie an: Nein oder Ja und geben Sie Name und Adresse an.",
      "angebot": null
    },
    {
      "felder": ["f118"],
      "frage": "Ist der/die Verletzte quellensteuerpflichtig? Bitte kreuzen Sie an: Ja oder Nein.",
      "angebot": null
    },
    {
      "felder": ["f119", "f120", "f121"],
      "frage": "Bestehen besondere Versicherungsverhältnisse? Bitte kreuzen Sie an: Freiwillige Versicherung des Arbeitgebers, Familienmitglied oder Entsandte/r.",
      "angebot": null
    },
    {
      "felder": ["f122"],
      "frage": "Bestehen andere Sozialversicherungsleistungen? Bitte geben Sie an, ob Anspruch auf Taggeld oder Rente bei einer anderen Sozialversicherung besteht und wo diese bezogen wird.",
      "angebot": null
    },
    {
      "felder": ["f127"],
      "frage": "Wie lautet der Name der obligatorischen Krankenversicherung des/der Verletzten (inklusive Police-Nr.)?",
      "angebot": null
    },
    {
      "felder": [],
      "frage": "Bitte unterschreiben Sie das Formular und geben Sie Ort und Datum an. (Keine Frage gestellt, da keine Eingabe erforderlich)",
      "angebot": null
    }
  ]
}
